type MessageShape<T> = {
  readonly [K in keyof T]: T[K] extends string
    ? string
    : T[K] extends Record<string, unknown>
      ? MessageShape<T[K]>
      : never;
};

export type Messages = MessageShape<typeof messages>;
export default messages;
